a<-commandArgs(TRUE);if(length(a)<3)stop("Usage: time_auc.R <pred.csv> <out> <times>");if(!requireNamespace("timeROC",quietly=TRUE)||!requireNamespace("ggplot2",quietly=TRUE))stop("Install timeROC and ggplot2");d<-read.csv(a[1],check.names=FALSE);out<-a[2];tt<-as.numeric(strsplit(a[3],",",TRUE)[[1]]);mods<-setdiff(names(d),c("ID","Time","Event"));dir.create(out,recursive=TRUE,showWarnings=FALSE);z<-do.call(rbind,lapply(mods,function(m){o<-timeROC::timeROC(T=d$Time,delta=d$Event,marker=d[[m]],cause=1,weighting="marginal",times=tt,iid=TRUE);data.frame(time=tt,AUC=o$AUC,model=m)}));write.csv(z,file.path(out,"time_auc.csv"),row.names=FALSE);p<-ggplot2::ggplot(z,ggplot2::aes(time,AUC,color=model))+ggplot2::geom_line(linewidth=.8)+ggplot2::geom_point()+ggplot2::geom_hline(yintercept=.7,linetype=2,color="grey60")+ggplot2::coord_cartesian(ylim=c(.5,1))+ggplot2::theme_classic()+ggplot2::labs(x="Time",y="Time-dependent AUC",color=NULL);ggplot2::ggsave(file.path(out,"time_auc.pdf"),p,width=7,height=5);ggplot2::ggsave(file.path(out,"time_auc.png"),p,width=7,height=5,dpi=300)
